import { Button } from "@mendix/ide-ui-components/button/Button";
import React, { ReactElement } from "react";
import { DivFlexColumn, DivFlexRow, StyledLabel } from "./elements/formelements";
import TextInputWithIcon from "./TextInputWithIcon";
import { ValidationError } from "@mendix/ide-ui-components/validation/types";

interface TextInputWithButtonProps {
    label?: string;
    ariaLabel: string;
    value: string;
    buttonCaption: string;
    onClick: () => void;
    buttonCaptionSecondary?: string;
    onClickSecondary?: () => void;
    placeholder?: string;
    hasMarginTop?: boolean;
    icon?: ReactElement | string;
    validate?: () => true | ValidationError | null | undefined;
}

const TextInputWithButton: React.FC<TextInputWithButtonProps> = ({
    label,
    ariaLabel,
    value,
    buttonCaption,
    onClick,
    buttonCaptionSecondary,
    onClickSecondary,
    placeholder,
    hasMarginTop = false,
    icon,
    validate,
}) => {
    const marginTop = hasMarginTop ? 8 : 0;
    return (
        <DivFlexRow marginTop={marginTop}>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>{label}</StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <DivFlexRow>
                    <DivFlexColumn fullWidth>
                        <TextInputWithIcon
                            ariaLabel={ariaLabel}
                            value={value}
                            placeholder={placeholder}
                            readOnly={true}
                            icon={icon}
                            validate={validate}
                        />
                    </DivFlexColumn>
                    <Button onPress={onClick}>{buttonCaption}</Button>
                    {buttonCaptionSecondary && <Button onPress={onClickSecondary}>{buttonCaptionSecondary}</Button>}
                </DivFlexRow>
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextInputWithButton;
