import { StudioProApi, SelectorResult, Microflows } from "@mendix/extensions-api";
import { Tool } from "../../types/tool";
import { getMicroflowByQualifiedName } from "../../utils/microflowUtils";
import { Agent } from "../../types/agent";
import { CommonModelEntities } from "../../constants/genAICommonsEntities";

export const handleSelectCustomDocument = async (
    studioPro: StudioProApi,
    tool: Tool,
    fieldName: keyof Tool,
    elementType?: string
): Promise<Tool | null> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        query: { elementType: elementType },
    });
    if (selectorResult.status === "ok") {
        const updatedTool: Tool = {
            ...tool,
            [fieldName]: selectorResult.selected.module + "." + selectorResult.selected.name,
        };
        return updatedTool;
    }
    return null;
};

export const handleValidateTool = async (
    field: keyof Tool,
    tool: Tool,
    studioPro: StudioProApi,
    agent: Agent
): Promise<true | string> => {
    const existingTools: Tool[] = agent.tools;

    switch (field) {
        case "name":
            if (!tool.name || tool.name.trim() === "") {
                return "Tool name cannot be empty.";
            }
            if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(tool.name)) {
                return "Tool name must start with a letter or underscore and contain only letters, numbers, and underscores.";
            }
            if (tool.name.length > 64) {
                return "Tool name cannot exceed 64 characters.";
            }
            if (existingTools && existingTools.some((t) => t.name === tool.name && t.id !== tool.id)) {
                return "Tool name must be unique.";
            }
            break;

        case "description": {
            if (!tool.description || tool.description.trim() === "") {
                return "Tool description cannot be empty.";
            }
            if (tool.description.length > 4096) {
                return "Tool description cannot exceed 4096 characters.";
            }
            break;
        }

        case "microflow": {
            const allowedMicroflowReturnTypes = [
                "DataTypes$StringType",
                "DataTypes$BooleanType",
                "DataTypes$IntegerType",
                "DataTypes$DecimalType",
                "DataTypes$FloatType",
                "DataTypes$DateTimeType",
                "DataTypes$VoidType",
                "DataTypes$EmptyType",
                "DataTypes$EnumerationType",
            ];

            const allowedObjectEntities = [CommonModelEntities.Request, CommonModelEntities.Tool];

            if (tool.toolType === "Microflow" && (!tool.microflow || tool.microflow.trim() === "")) {
                return "Microflow must be selected for Microflow tool.";
            }
            const microflow: Microflows.Microflow | null = await getMicroflowByQualifiedName(
                studioPro,
                tool.microflow || ""
            );
            if (microflow === null) {
                return "Selected microflow does not exist.";
            }
            if (microflow.microflowReturnType.$Type !== "DataTypes$StringType") {
                return "Tool microflow must return a String.";
            }
            const microflowObjects: Microflows.MicroflowObject[] | undefined = microflow.objectCollection.objects;
            if (microflowObjects) {
                for (const param of microflowObjects) {
                    if (param.$Type === "Microflows$MicroflowParameterObject") {
                        if (allowedMicroflowReturnTypes.includes(param.variableType.$Type)) {
                            continue;
                        } else if (
                            param.variableType.$Type === "DataTypes$ObjectType" &&
                            allowedObjectEntities.includes(param.variableType.entity)
                        ) {
                            continue;
                        } else {
                            return `Tool microflow parameter "${param.name}" has an unsupported type. Only primitive types and GenAICommons.Request or GenAICommons.Tool objects are allowed.`;
                        }
                    }
                }
            }
            break;
        }

        case "toolType": {
            if (!tool.toolType) {
                return "Tool type cannot be empty.";
            }
            break;
        }
        default:
            return true;
    }
    return true;
};
